/// The words the grammar reads, a word's code its place plus one, as the lean lexer's `WORD_LIST`.
const WORD_LIST: [&[u8]; 123] = [
    b"as", b"typealias", b"class", b"fun", b"interface", b"val", b"var", b"object", b"this", b"super", b"for", b"in",
    b"while", b"do", b"if", b"else", b"when", b"try", b"throw", b"return", b"continue", b"break", b"is", b"true",
    b"false", b"null", b"@", b":", b"[", b"]", b"*", b"=", b"{", b"}", b"(", b",",
    b")", b"<", b">", b".", b";", b"&", b"?", b"->", b"..", b"..<", b"?:", b"!",
    b"&&", b"||", b"::", b"+=", b"-=", b"*=", b"/=", b"%=", b"!=", b"!==", b"==", b"===",
    b"<=", b">=", b"+", b"-", b"/", b"%", b"++", b"--", b"!!", b"?.", b"annotation", b"file",
    b"package", b"import", b"enum", b"suspend", b"by", b"where", b"init", b"companion", b"get", b"set", b"constructor", b"dynamic",
    b"data", b"catch", b"finally", b"sealed", b"inner", b"value", b"override", b"lateinit", b"public", b"private", b"internal", b"protected",
    b"out", b"tailrec", b"operator", b"infix", b"inline", b"external", b"const", b"abstract", b"final", b"open", b"vararg", b"noinline",
    b"crossinline", b"reified", b"expect", b"actual", b"field", b"property", b"receiver", b"param", b"setparam", b"delegate", b"L", b"u",
    b"U", b"uL", b"UL",
];

/// Up to 8 bytes as one word of memory: little-endian, zeros past them.
const fn word_key(s: &[u8]) -> u64 {
    let (mut v, mut i) = (0u64, 0);
    while i < s.len() {
        v |= (s[i] as u64) << (8 * i);
        i += 1;
    }
    v
}

/// A word's slot in `WORDS`: its first 8 bytes and its length, hashed by a multiplier under which the 123 words take
/// 123 slots, as the lean lexer's `word_slot`.
const fn word_slot(k: u64, len: usize) -> usize {
    ((k ^ len as u64).wrapping_mul(0x2b1b725f92866a4b) >> 54) as usize
}

/// Each slot's word (`word_at`): its first 8 bytes, the next 8, its length, its code (0: none), as the lean lexer's
/// `WORDS`.
static WORDS: [(u64, u64, u32, u32); 1024] = {
    let mut t = [(0, 0, 0, 0); 1024];
    let mut i = 0;
    while i < WORD_LIST.len() {
        let w = WORD_LIST[i];
        let (head, tail) = w.split_at(if w.len() > 8 { 8 } else { w.len() });
        let slot = word_slot(word_key(head), w.len());
        assert!(t[slot].3 == 0, "two words in a slot");
        t[slot] = (word_key(head), word_key(tail), w.len() as u32, i as u32 + 1);
        i += 1;
    }
    t
};

/// A token's word: the code of the word its `len` bytes from `s` are, 0 for none, as the lean lexer's `word_code`. Its
/// first 8 bytes, masked to its length, and the length, hashed by one multiply into `WORDS`; its bytes 8 to 16 masked
/// the same, compared with the first and the length in one test (lean's `ninth`), without a branch.
#[inline(always)]
fn word_at(src: &[u8], s: usize, len: usize) -> u32 {
    let raw = load8(src, s);
    let rest = load8(src, s + 8);
    let k = raw & (u64::MAX >> (64 - 8 * len.clamp(1, 8)));
    let t = rest & u64::MAX.checked_shr(128 - 8 * len.clamp(8, 16) as u32).unwrap_or(0);
    let (key, tail, l, code) = WORDS[word_slot(k, len)];
    code & 0u32.wrapping_sub(u32::from((key == k) & (tail == t) & (l as usize == len)))
}

/// The 8 bytes at `i`, little-endian, zeros past the file.
#[inline(always)]
fn load8(src: &[u8], i: usize) -> u64 {
    match src.get(i..i + 8) {
        Some(b) => u64::from_le_bytes(b.try_into().expect("8 bytes")),
        None => load8_at_end(src, i),
    }
}

/// `load8` within 8 bytes of the file's end.
#[cold]
#[inline(never)]
fn load8_at_end(src: &[u8], i: usize) -> u64 {
    let rest = src.get(i..).unwrap_or(&[]);
    let have = rest.len().min(8);
    let mut w = [0u8; 8];
    w[..have].copy_from_slice(&rest[..have]);
    u64::from_le_bytes(w)
}


/// The marks tier 1's records leave to tier 2 (decisions 0623, 0655): those it asks of the bytes (`ASKED`), those whose
/// token tests it asks (`TESTED`), and the token marks its code reads no bit of (it asks them of the tokens).
pub const UNRECORDED: u32 = 0xe;

/// The marks whose token tests tier 2 asks (decision 0655 step 6): none, the records hold them.
pub const TESTED: u32 = 0;

/// Whether a token test of mark `b` holds at grammar token `j`: never asked.
pub fn tested(src: &[u8], recs: &[Rec], xs: &[Rec], j: usize, b: u32) -> bool {
    let _ = (src, recs, xs, j, b);
    false
}

/// The gap marks tier 1 writes one bit for, the carrier's, the others of its mask asked of it where a rule reads one
/// (decision 0703), as the lean parser asks `asi` of a token's `nl`.
pub const DERIVED: u32 = 0xe;

/// Whether derived mark `b` holds at a token whose marks are `marks`, after a token of word `before`.
#[inline(always)]
pub fn derived(b: u32, marks: u32, before: u32) -> bool {
    match b {
        1 => marks >> 0 & 1 == 1,
        2 => marks >> 0 & 1 == 1 && !matches!(before, 41),
        3 => marks >> 0 & 1 == 1 && !matches!(before, 41),
        _ => false,
    }
}

/// Marks `bits` with the carriers of the derived ones (`DERIVED`): an extra's own, read of its code.
#[inline(always)]
pub const fn carried(bits: u32) -> u32 {
    let mut r = bits;
    if bits >> 1 & 1 == 1 {
        r |= 1 << 0;
    }
    if bits >> 2 & 1 == 1 {
        r |= 1 << 0;
    }
    if bits >> 3 & 1 == 1 {
        r |= 1 << 0;
    }
    r
}

/// The gap marks tier 2 asks of the bytes, where a rule asks one (decision 0623 step 5), by their bits: tier 1's
/// records hold only its token tests' hits of them.
pub const ASKED: u32 = 0x0;

/// Whether gap mark `b` holds over `src[from..to]`, the bytes since the grammar token before's first byte (`before` its
/// word), as the lean parser asks whether a token is on a line.
#[inline]
pub fn gap(src: &[u8], from: usize, to: usize, before: u32, b: u32) -> bool {
    let _ = (src, from, to, before, b);
    false
}

/// Block `q`'s 64 bytes; the last block's past the file are 0x00.
#[inline(always)]
fn block(src: &[u8], q: usize) -> [u8; 64] {
    let at = 64 * q;
    match src.get(at..at + 64) {
        Some(b) => b.try_into().expect("64 bytes"),
        None => {
            let mut b = [0u8; 64];
            b[..src.len() - at].copy_from_slice(&src[at..]);
            b
        }
    }
}

/// `prev(x, k)`'s word `i`: each byte's bit from `k` bytes before.
#[inline(always)]
fn prev(x: &[u64], i: usize, k: u32) -> u64 {
    x[i] << k | if i > 0 { x[i - 1] >> (64 - k) } else { 0 }
}

/// `next(x, k)`'s word `i`: each byte's bit from `k` bytes after.
#[inline(always)]
fn next(x: &[u64], i: usize, k: u32) -> u64 {
    x[i] >> k | x.get(i + 1).map_or(0, |w| w << (64 - k))
}

/// `fill(s, e)`: from each byte of `s` up to, not including, the next of `e`; one add a word,
/// its carry the next word's.
fn fill(s: &[u64], e: &[u64]) -> Vec<u64> {
    let mut cin = 0u64;
    s.iter()
        .zip(e)
        .map(|(&s, &e)| {
            let b = !e | s;
            let into = s.wrapping_add(b).wrapping_add(cin) ^ s ^ b;
            let f = s | (!e & into);
            cin = f >> 63;
            f
        })
        .collect()
}

/// `escaped(x)`: simdjson's escaped bytes, each byte after an odd run of `x`'s, a word at a time
/// with one carry bit.
fn escaped(x: &[u64]) -> Vec<u64> {
    const ODD: u64 = 0xaaaa_aaaa_aaaa_aaaa;
    let mut carry = 0u64;
    x.iter()
        .map(|&bs| {
            if bs == 0 {
                return std::mem::take(&mut carry);
            }
            let potential = bs & !carry;
            let series = ((potential << 1) | ODD).wrapping_sub(potential);
            let escape_and_terminal = series ^ ODD;
            let escaped = escape_and_terminal ^ (bs | carry);
            carry = (escape_and_terminal & bs) >> 63;
            escaped
        })
        .collect()
}

/// Whether `x` holds anywhere.
fn any(x: &[u64]) -> bool {
    x.iter().any(|&w| w != 0)
}

/// Whether `x` holds at byte `i`.
#[inline(always)]
fn bit(x: &[u64], i: usize) -> bool {
    x.get(i / 64).is_some_and(|w| w >> (i % 64) & 1 == 1)
}

/// `x`'s first bit at or after byte `from`, a word at a time.
#[inline(always)]
fn first_bit(x: &[u64], from: usize) -> Option<usize> {
    let mut q = from / 64;
    let mut w = x.get(q)? & (!0u64 << (from % 64));
    while w == 0 {
        q += 1;
        w = *x.get(q)?;
    }
    Some(64 * q + w.trailing_zeros() as usize)
}

/// The first byte at or after `from` that `x` does not hold, before `n`.
#[inline(always)]
fn first_clear(x: &[u64], from: usize, n: usize) -> Option<usize> {
    let mut q = from / 64;
    if from >= n {
        return None;
    }
    let mut w = !x.get(q).copied().unwrap_or(0) & (!0u64 << (from % 64));
    while w == 0 {
        q += 1;
        if 64 * q >= n {
            return None;
        }
        w = !x.get(q).copied().unwrap_or(0);
    }
    let i = 64 * q + w.trailing_zeros() as usize;
    (i < n).then_some(i)
}

/// The last byte of the run of `r`'s bits after byte `s` with one bit of `d` in it at most: the second ends the
/// run before it, as a lexer reads a number's one `.` and stops at the next.
#[inline(always)]
fn run_once_last(r: &[u64], d: &[u64], s: usize) -> usize {
    let l = run_last(r, s);
    match first_in(d, s + 1, l).and_then(|p| first_in(d, p + 1, l)) {
        Some(q) => q - 1,
        None => l,
    }
}

/// The last byte of the run of `r`'s bits after byte `s`: `s` with none, a word at a time.
#[inline(always)]
fn run_last(r: &[u64], s: usize) -> usize {
    let mut i = s + 1;
    loop {
        let Some(&w) = r.get(i / 64) else { return i - 1 };
        let ones = (!(w >> (i % 64))).trailing_zeros() as usize;
        let left = 64 - i % 64;
        if ones < left {
            return i + ones - 1;
        }
        i += left;
    }
}

/// Whether `x` holds anywhere in bytes `a..=b` (none where `a > b`), its words to `b`'s alone read.
#[inline(always)]
fn any_in(x: &[u64], a: usize, b: usize) -> bool {
    first_in(x, a, b).is_some()
}

/// The first byte in `a..=b` that `x` holds, a word at a time.
fn first_in(x: &[u64], a: usize, b: usize) -> Option<usize> {
    if a > b {
        return None;
    }
    let mut q = a / 64;
    let mut w = x.get(q).copied().unwrap_or(0) & (!0u64 << (a % 64));
    loop {
        if q == b / 64 && b % 64 != 63 {
            w &= (1u64 << (b % 64 + 1)) - 1;
        }
        if w != 0 {
            return Some(64 * q + w.trailing_zeros() as usize);
        }
        if q == b / 64 {
            return None;
        }
        q += 1;
        w = x.get(q).copied().unwrap_or(0);
    }
}

/// The last byte in `a..=b` that `x` holds, a word at a time.
fn last_in(x: &[u64], a: usize, b: usize) -> Option<usize> {
    if a > b {
        return None;
    }
    let mut q = b / 64;
    let mut w = x.get(q).copied().unwrap_or(0);
    if b % 64 != 63 {
        w &= (1u64 << (b % 64 + 1)) - 1;
    }
    loop {
        if q == a / 64 {
            w &= !0u64 << (a % 64);
        }
        if w != 0 {
            return Some(64 * q + 63 - w.leading_zeros() as usize);
        }
        if q == a / 64 {
            return None;
        }
        q -= 1;
        w = x.get(q).copied().unwrap_or(0);
    }
}

/// `x`'s bits in bytes `a..=b`, a word at a time.
fn count_in(x: &[u64], a: usize, b: usize) -> u32 {
    let mut n = 0;
    for q in a / 64..=b / 64 {
        let mut w = x.get(q).copied().unwrap_or(0);
        if q == a / 64 {
            w &= !0u64 << (a % 64);
        }
        if q == b / 64 && b % 64 != 63 {
            w &= (1u64 << (b % 64 + 1)) - 1;
        }
        n += w.count_ones();
    }
    n
}

/// `v`'s bits at bytes `a..=b` made `m`'s.
#[inline(always)]
fn put(v: &mut [u64], m: &[u64], a: usize, b: usize) {
    let mut i = a;
    while i <= b {
        let (q, r) = (i / 64, i % 64);
        let k = (b + 1 - i).min(64 - r);
        let w = (if k == 64 { !0 } else { (1u64 << k) - 1 }) << r;
        v[q] = v[q] & !w | m[q] & w;
        i += k;
    }
}

/// `v`'s bits at bytes `a..=b` cleared.
#[inline(always)]
fn clear(v: &mut [u64], a: usize, b: usize) {
    let mut i = a;
    while i <= b {
        let (q, r) = (i / 64, i % 64);
        let k = (b + 1 - i).min(64 - r);
        v[q] &= !((if k == 64 { !0 } else { (1u64 << k) - 1 }) << r);
        i += k;
    }
}

/// Bytes `a..b` set in `v` (cut to its words).
#[inline(always)]
fn set(v: &mut [u64], a: usize, b: usize) {
    let b = b.min(64 * v.len());
    let mut i = a;
    while i < b {
        let (q, r) = (i / 64, i % 64);
        let k = (b - i).min(64 - r);
        v[q] |= (if k == 64 { !0 } else { (1u64 << k) - 1 }) << r;
        i += k;
    }
}
